import{_ as t,o as n,c as s,a2 as a}from"./chunks/framework.C4u7U0Dw.js";const q=JSON.parse('{"title":"第 37 周 · 创刊号（2026-09-07 ~ 09-13）","description":"创刊说明 + 第 1 周任务（把每周重复的事交给 AI）+ 装备 001（三段式提示词骨架）+ 编辑部实测 001","frontmatter":{"title":"第 37 周 · 创刊号（2026-09-07 ~ 09-13）","description":"创刊说明 + 第 1 周任务（把每周重复的事交给 AI）+ 装备 001（三段式提示词骨架）+ 编辑部实测 001","date":"2026-09-12T00:00:00.000Z"},"headers":[],"relativePath":"community/weekly/2026-w37.md","filePath":"community/weekly/2026-w37.md"}'),r={name:"community/weekly/2026-w37.md"};function e(l,o,i,p,g,u){return n(),s("div",null,[...o[0]||(o[0]=[a(`<h1 id="第-37-周-·-创刊号-2026-09-07-09-13" tabindex="-1">第 37 周 · 创刊号（2026-09-07 ~ 09-13） <a class="header-anchor" href="#第-37-周-·-创刊号-2026-09-07-09-13" aria-label="Permalink to &quot;第 37 周 · 创刊号（2026-09-07 ~ 09-13）&quot;">​</a></h1><blockquote><p>每周三期：<strong>周一任务 / 周三装备 / 周日上墙与周报</strong>。 本期是创刊号，于 2026-09-12 一次补齐三期。往后严格按周一 / 周三 / 周日的节奏走。</p></blockquote><hr><h2 id="为什么会有这份周刊" tabindex="-1">为什么会有这份周刊 <a class="header-anchor" href="#为什么会有这份周刊" aria-label="Permalink to &quot;为什么会有这份周刊&quot;">​</a></h2><p>先说清一件事：<strong>这个社区不是&quot;看看别人怎么做&quot;的地方。</strong></p><p>我们只做一件事——<strong>把 AI 用进你手上那件真实的事里</strong>，然后把结果交出来。</p><p>问题是，一个人干活很难坚持：想到好点子没人接话，卡住了没人搭手，做完了没人知道。所以这里立了<strong>三拍</strong>，让&quot;干&quot;这件事有节奏：</p><ul><li><strong>周一</strong>给你任务：这周做什么，定死。</li><li><strong>周三</strong>给你装备：一件能直接用的东西，让你不至于空手上阵。</li><li><strong>周日</strong>上墙：把交付物摆出来，也把没做到的地方摆出来。</li></ul><p>还有一条，是这份周刊存在的底线——</p><blockquote><p><strong>没有成员作业的周，由「编辑部实测记录」顶上。我自己真跑一遍，把过程写出来。</strong> 不编故事，但也不空着。</p></blockquote><hr><h2 id="📓-周一-·-本周任务-第-1-周" tabindex="-1">📓 周一 · 本周任务（第 1 周） <a class="header-anchor" href="#📓-周一-·-本周任务-第-1-周" aria-label="Permalink to &quot;📓 周一 · 本周任务（第 1 周）&quot;">​</a></h2><blockquote><p><strong>把一件你每周都要重复做的事，交给 AI 做一遍</strong></p></blockquote><p><strong>为什么做这个</strong>：先别管学到多少，先尝到一次&quot;真的省事了&quot;。</p><p><strong>怎么做（≤ 40 分钟）</strong></p><ol><li>想一件你<strong>每周至少做一次</strong>、每次要花 <strong>10 分钟以上</strong>的事（写周报、整理表格、回邮件、做汇总、写通知……）</li><li>打开 MomaWork，用大白话把这件事讲给它——<strong>不用懂提示词</strong>，怎么跟同事说就怎么说</li><li>让它先做一遍，你只改不对的地方</li><li>记下两个数：<strong>以前要多久 / 现在要多久</strong></li></ol><p><strong>交付物</strong>：一张前后对比（截图最好，一句话也行） <strong>交到哪</strong>：加我微信直接发我，或在群里 @我 <strong>上墙标准</strong>：写清&quot;以前怎么做 / 现在什么样 / 别人能不能照做&quot;三样（见首页「📮 作业交上来之后」一节）</p><hr><h2 id="🛠-周三-·-装备-001-·-三段式提示词骨架" tabindex="-1">🛠 周三 · 装备 001 · 三段式提示词骨架 <a class="header-anchor" href="#🛠-周三-·-装备-001-·-三段式提示词骨架" aria-label="Permalink to &quot;🛠 周三 · 装备 001 · 三段式提示词骨架&quot;">​</a></h2><blockquote><p><strong>一句话请求 ≈ 让它猜；给&quot;角色 + 任务 + 约束 + 输出格式&quot;≈ 给它图纸。</strong></p></blockquote><p><strong>怎么用</strong></p><ol><li><strong>角色</strong>：一句话说清&quot;谁在说话&quot;，越具体越好。</li><li><strong>任务</strong>：要它产出的<strong>成品是什么</strong>（一份 200 字周报、一份 6 条清单）。</li><li><strong>约束</strong>：不许做什么（不要形容词、不许编、每条 30 字内）。</li><li><strong>输出格式</strong>：Markdown？表格？三节？先定死。</li></ol><p><strong>成品样例（复制就能用）</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>角色：你是【每周向团队同步进展的项目负责人】，只讲事实，句子短。</span></span>
<span class="line"><span>任务：根据我下面给的原始记录，写一份【200 字以内的周报】。</span></span>
<span class="line"><span>约束：</span></span>
<span class="line"><span>- 分三节：【本周完成 / 遇到的问题 / 下周计划】</span></span>
<span class="line"><span>- 每条不超过 30 字，不要形容词</span></span>
<span class="line"><span>- 遇到的问题必须写清&quot;卡在哪一步、需要谁配合&quot;</span></span>
<span class="line"><span>- 原始记录里没有的，一个字都不要加</span></span>
<span class="line"><span>输出格式：Markdown 三个小节，每节一个无序列表。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>原始记录：</span></span>
<span class="line"><span>1. …</span></span></code></pre></div><p><strong>来源</strong>：Anthropic《Prompt engineering overview》 <a href="https://docs.claude.com/en/docs/build-with-claude/prompt-engineering/overview" target="_blank" rel="noreferrer">https://docs.claude.com/en/docs/build-with-claude/prompt-engineering/overview</a>（获取于 2026-09-12）；OpenAI《Prompt engineering》 <a href="https://platform.openai.com/docs/guides/prompt-engineering" target="_blank" rel="noreferrer">https://platform.openai.com/docs/guides/prompt-engineering</a>（获取于 2026-09-12）</p><p><strong>一句话提醒</strong>：约束里写&quot;要专业&quot;没用，写&quot;<strong>不要形容词</strong>&quot;才有用。</p><hr><h2 id="🪧-周日-·-上墙与周报-001" tabindex="-1">🪧 周日 · 上墙与周报 001 <a class="header-anchor" href="#🪧-周日-·-上墙与周报-001" aria-label="Permalink to &quot;🪧 周日 · 上墙与周报 001&quot;">​</a></h2><h3 id="本周上墙" tabindex="-1">本周上墙 <a class="header-anchor" href="#本周上墙" aria-label="Permalink to &quot;本周上墙&quot;">​</a></h3><p><strong>本周还没有人交作业 —— 第一面墙空着。</strong></p><p>空着就是空的，不凑数。第 1 周任务（把重复的事交给 AI）本周日截止，谁先交，谁就是墙上第一份，我会注明&quot;第 1 位交作业的人&quot;，不做任何美化。</p><h3 id="编辑部实测-001-·-同一件事-两种问法" tabindex="-1">编辑部实测 001 · 同一件事，两种问法 <a class="header-anchor" href="#编辑部实测-001-·-同一件事-两种问法" aria-label="Permalink to &quot;编辑部实测 001 · 同一件事，两种问法&quot;">​</a></h3><p><strong>我做了什么</strong>：同一件事（写周报），分别用&quot;一句话请求&quot;和&quot;三段式骨架&quot;各跑一次。</p><ul><li><strong>A 版</strong>：只说&quot;帮我写一份周报&quot; → 出来的东西结构对，但全是&quot;积极推进中&quot;&quot;取得了良好进展&quot;。要能用，基本得重写，等于没省时间。</li><li><strong>B 版</strong>：用上面装备 001 的骨架（角色 + 任务 + 约束 + 输出格式 + 编号原始记录）→ <strong>一次成型</strong>，三节齐、字数够，&quot;遇到的问题&quot;写成了&quot;微信建群依赖人数，目前 0 人，需要先有 3–5 人再建&quot;。我只改了一个词。</li></ul><p><strong>踩的坑</strong>（这三条比结论有用）：</p><ol><li>约束里写&quot;要专业&quot;没用，模型照样堆形容词；换成&quot;<strong>不要形容词</strong>&quot;才有用。</li><li>&quot;<strong>不要编</strong>&quot;必须写进约束，否则它会顺手给你补两条进度。</li><li>原始记录<strong>用编号列表</strong>给，比写成一段话稳定得多。</li></ol><p><strong>结论</strong>：这条骨架可直接复制去用，把&quot;原始记录&quot;换成你的就行。</p><h3 id="资源-技能上新-本周" tabindex="-1">资源 / 技能上新（本周） <a class="header-anchor" href="#资源-技能上新-本周" aria-label="Permalink to &quot;资源 / 技能上新（本周）&quot;">​</a></h3><ul><li>周刊机制上线：<strong>每周一 / 周三 / 周日</strong>各一期，归档在 <code>/community/weekly/</code></li><li>运营素材增至 <strong>5 份新增</strong>：内容日历（12 周 · 36 期）、周三装备库（12 件）、编辑部实测记录、参考来源与学习日志、周刊模板与发布清单</li><li>来源登记：所有外部知识均按&quot;标题 + 链接 + 获取日期&quot;登记（编辑部台账，并在每期装备的页面上直接标注）</li></ul><h3 id="下周预告-第-38-周-·-09-14-09-20" tabindex="-1">下周预告（第 38 周 · 09-14 ~ 09-20） <a class="header-anchor" href="#下周预告-第-38-周-·-09-14-09-20" aria-label="Permalink to &quot;下周预告（第 38 周 · 09-14 ~ 09-20）&quot;">​</a></h3><ul><li><strong>周一</strong>：第 2 周任务 —— 把你最常说的三句话，写成一个能复用的提示词</li><li><strong>周三</strong>：装备 002 —— 先给样例，再让它干（少样本示例）</li><li><strong>周日</strong>：上墙与周报 002 —— 本周交付物 + 编辑部实测 002</li></ul>`,41)])])}const d=t(r,[["render",e]]);export{q as __pageData,d as default};
